/** Direct sum of birth-death stationary probabilities including the geometric tail. */
export function independentAutumnQueue(arrivalsPerHour:number,meanServiceMinutes:number,servers:number){const a=arrivalsPerHour*meanServiceMinutes/60,rho=a/servers;if(rho>=1)return Infinity;const factorial=(n:number)=>{let r=1;for(let k=2;k<=n;k++)r*=k;return r;};let denominator=0;for(let n=0;n<servers;n++)denominator+=a**n/factorial(n);const tail=a**servers/factorial(servers);denominator+=tail/(1-rho);const p0=1/denominator;return p0*tail*rho/(1-rho)**2;}
export function independentAutumnMinimum(arrivals:number,service:number,limitSeconds:number){const gap=3600/arrivals;for(let s=Math.floor(arrivals*service/60)+1;s<100;s++)if(independentAutumnQueue(arrivals,service,s)*gap<=limitSeconds)return s;throw Error('NO_QUEUE_SOLUTION');}
/** Each source choice is checked against the three distinct duties, not a producer answer ID. */
export function independentAutumnRoles(row:string[]){const roles:Record<string,string>={'音声ゲートウェイ':'公衆電話網から受ける','コールサーバ':'VoIP接続を制御する','着信分配情報サーバ':'席状態を認識し接続先を決める','顧客情報サーバ':'履歴検索と結果記録'};return row.map(name=>roles[name]).every((r,i)=>r===['公衆電話網から受ける','VoIP接続を制御する','席状態を認識し接続先を決める'][i]);}
